1216	/** Spread damage: place `amount` HP on EACH of the opponent's Benched Pokémon
1217	    (§8.5 — Weakness/Resistance never apply on the Bench, so it is flat there).
1218	    A benched Pokémon's own continuous damage REDUCTION still applies though
1219	    (Bouffalant "Bouffer" / a defending Tool — the passive that is not
1220	    Active-only), floored at 0; the attacker's pre-W/R bonus (Vitality Band) is
1221	    Active-target-only and does NOT reach the Bench. One DAMAGE_DEALT per benched
1222	    Pokémon (seat/uid name the DEFENDER, as everywhere). Only raises damage — the
1223	    KO check runs in attack.ts's epilogue, so this never KOs or ends the game
1224	    (interpreter header). */
1225	function spreadDamage(
1226	  state: GameState,
1227	  amount: number,
1228	  ctx: EffectContext,
1229	  events: GameEvent[],
1230	): GameState {
1231	  if (amount <= 0) return state;
1232	  const opponent = otherSeat(ctx.seat);
1233	  const side = state.players[opponent];
1234	  if (side.bench.length === 0) return state;
1235	  const bench = side.bench.map((pokemon) => {
1236	    const uid = topUid(pokemon);
1237	    if (uid === undefined) return pokemon;
1238	    const reduction = passivesOf(state, pokemon).damageReductionAfterWR;
1239	    const dealt = Math.max(0, amount - reduction);
1240	    const damage = pokemon.damage + dealt;
1241	    events.push({
1242	      type: "DAMAGE_DEALT",
1243	      seat: opponent,
1244	      uid,
1245	      base: amount,
1246	      weakness: null,
1247	      resistance: null,
1248	      reduction: reduction > 0 ? reduction : undefined,
1249	      dealt,
1250	      damage,
1251	    });
1252	    return { ...pokemon, damage };
1253	  });
1254	  return withSide(state, opponent, { ...side, bench });
1255	}
