1257	/** Snipe: put `amount` HP of damage counters on the opponent's Benched Pokémon
1258	    named by `refs` (the forced set, or the ones the player chose — validated
1259	    upstream, so only refs that are the opponent's own bench slots land). Flat —
1260	    a counter placement, NOT attack damage, so no Weakness/Resistance and no
1261	    reduction passive (Bouffer reduces "damage from attacks", which a placed
1262	    counter is not — the damageActive rule). One COUNTERS_PLACED source "ability"
1263	    per Pokémon actually hit. Only raises damage; the KO check runs in the
1264	    caller's mid-turn sweep (flow.ts), so this never KOs. */
1265	function placeSnipe(
1266	  state: GameState,
1267	  refs: readonly PokemonRef[],
1268	  amount: number,
1269	  deals: boolean,
1270	  ctx: EffectContext,
1271	  events: GameEvent[],
1272	): GameState {
1273	  if (amount <= 0) return state;
1274	  const opponent = otherSeat(ctx.seat);
1275	  // The Active target — `opponentAny` only (Fezandipiti ex "Cruel Arrow"). §8.5:
1276	  // Weakness/Resistance apply ONLY to the Active/Defending Pokémon, so a snipe that
1277	  // lands on the Active goes THROUGH W/R, unlike every Bench target below. A
1278	  // put-counter snipe never offers the Active (its candidates are Bench-only), so
1279	  // this branch is reached with deals=true.
1280	  let next = state;
1281	  if (refs.some((r) => r.seat === opponent && r.spot.spot === "active")) {
1282	    next = snipeActive(next, amount, ctx, events);
1283	  }
1284	  // Bench targets — flat (no W/R). Batched in one map so a count-N snipe (Hawlucha)
1285	  // still lands as before.
1286	  const targeted = new Set<number>();
1287	  for (const ref of refs) {
1288	    if (ref.seat === opponent && ref.spot.spot === "bench") targeted.add(ref.spot.index);
1289	  }
1290	  if (targeted.size === 0) return next;
1291	  const side = next.players[opponent];
1292	  const bench = side.bench.map((pokemon, index) => {
1293	    if (!targeted.has(index)) return pokemon;
1294	    const uid = topUid(pokemon);
1295	    if (uid === undefined) return pokemon;
1296	    if (!deals) {
1297	      // The default put-counter snipe (Hawlucha / Meowscarada): flat, no W/R and
1298	      // no reduction passive (a placed counter is not "damage from an attack").
1299	      events.push({ type: "COUNTERS_PLACED", seat: opponent, uid, amount, source: "ability" });
1300	      return { ...pokemon, damage: pokemon.damage + amount };
1301	    }
1302	    // Wo-Chien "Covetous Ivy": ATTACK DAMAGE to a Benched Pokémon — no Weakness/
1303	    // Resistance (§8.5, Benched), but a benched reduction passive still applies,
1304	    // exactly like spreadDamage. Emitted as DAMAGE_DEALT, so the log reads "dealt"
1305	    // rather than "counters placed".
1306	    const reduction = passivesOf(next, pokemon).damageReductionAfterWR;
1307	    const dealt = Math.max(0, amount - reduction);
1308	    events.push({
1309	      type: "DAMAGE_DEALT",
1310	      seat: opponent,
1311	      uid,
1312	      base: amount,
1313	      weakness: null,
1314	      resistance: null,
1315	      reduction: reduction > 0 ? reduction : undefined,
1316	      dealt,
1317	      damage: pokemon.damage + dealt,
1318	    });
1319	    return { ...pokemon, damage: pokemon.damage + dealt };
1320	  });
1321	  return withSide(next, opponent, { ...side, bench });
1322	}
