1324	/** The Active-target arm of an `opponentAny` snipe (Fezandipiti ex "Cruel Arrow"
1325	    when the pick lands on the Active). Unlike the Bench arm, this runs the FULL §8.5
1326	    pipeline — base + the attacker's continuous pre-W/R bonus → ×Weakness →
1327	    −Resistance → −reduction, floored at 0 — read off the attacker's and the target's
1328	    printed cards, byte-for-byte attack.ts's main hit. The continuous bonus IS
1329	    included here (unlike the Bench arm): Vitality Band's "+10 to your opponent's
1330	    ACTIVE before Weakness/Resistance" applies precisely because the target is the
1331	    Active — the same reason the Bench arm correctly omits it. Only the main attack's
1332	    OWN printed base/scaling is absent (the snipe's `amount` is its whole base). */
1333	function snipeActive(
1334	  state: GameState,
1335	  amount: number,
1336	  ctx: EffectContext,
1337	  events: GameEvent[],
1338	): GameState {
1339	  const opponent = otherSeat(ctx.seat);
1340	  const target = activeTop(state, opponent);
1341	  if (target === null) return state;
1342	  const attacker = activeTop(state, ctx.seat);
1343	  const bonus = attacker === null ? 0 : attackerPreWRBonus(state, attacker.active, ctx.seat, target.card);
1344	  const weakness = attacker === null ? null : weaknessOf(attacker.card, target.card);
1345	  const resistance = attacker === null ? null : resistanceOf(attacker.card, target.card);
1346	  const afterWR = Math.max(
1347	    0,
1348	    applyDamageModifier(applyDamageModifier(amount + bonus, weakness), resistance),
1349	  );
1350	  const reduction = passivesOf(state, target.active).damageReductionAfterWR;
1351	  const dealt = Math.max(0, afterWR - reduction);
1352	  events.push({
1353	    type: "DAMAGE_DEALT",
1354	    seat: opponent,
1355	    uid: target.uid,
1356	    base: amount,
1357	    bonus: bonus > 0 ? bonus : undefined,
1358	    weakness,
1359	    resistance,
1360	    reduction: reduction > 0 ? reduction : undefined,
1361	    dealt,
1362	    damage: target.active.damage + dealt,
1363	  });
1364	  return withActive(state, opponent, { ...target.active, damage: target.active.damage + dealt });
1365	}
