619	      const amount = snipeAmount(op, state, ctx);
620	      if (amount <= 0) return { done: state };
621	      const declinable = op.optional === true;
622	      // §8.6: with fewer candidates than the printed number, take them all.
623	      const take = Math.min(op.count, candidates.length);
624	      if (!declinable && candidates.length <= op.count) {
